export type Cue={id:string;start:number;end:number;text:string;speaker?:string|null;speaker_id?:string;[key:string]:unknown};
export type Source={language:string;source_url:string;cues:Cue[]};
export type Block={id:string;heading:string;paragraphs:string[];source_refs:string[]};
export type Edition={id:string;kind:'interview';title:string;source_snapshot_id:string;created_at:string;revision:number;method:'manual'|'model';generation?:{task_id:string;provider:'codex'|'claude';model?:string};coverage:'full';blocks:Block[];media_identity?:string};
export type EditionExcerpt={id:string;edition_id:string;block_id:string;source_snapshot_id:string;created_at:string;from:number;to:number;text:string;block_text:string;source_refs:string[]};
export type EditionState={version:1;snapshots:Array<{id:string;source:Source}>;editions:Edition[];excerpts:EditionExcerpt[];jobs?:EditionJob[];answers?:EditionAnswer[];position?:{edition_id:string;block_id:string}};
export type Document={segments:Cue[];reading_editions?:EditionState;[key:string]:unknown};
export const LIMITS:{editions:number;cues:number;characters:number;excerpts:number};
export function validate(value:unknown):EditionState|undefined;
export function snapshot(doc:Document):Source;
export function state(doc:Document):EditionState;
export function freshness(doc:Document,edition:Edition):'current'|'stale';
export function sourceFor(doc:Document,edition:Edition):Source;
export function turns(doc:Document):Array<{speaker:string|null;start:number;end:number;paragraphs:string[];source_refs:string[]}>;
export function create<T extends Document>(doc:T,options:{id:string;snapshotId:string;createdAt:string;title?:string;mediaIdentity?:string}):T;
export function edit<T extends Document>(doc:T,editionId:string,blockId:string,changes:{heading:string;text:string},expectedRevision:number):T;
export function resolve(doc:Document,edition:Edition,block:Block):{cues:Cue[];ranges:Array<{start:number;end:number}>;speaker:string|null;current:boolean};
export function resolver(doc:Document,edition:Edition):(block:Block)=>ReturnType<typeof resolve>;
export function bookmark<T extends Document>(doc:T,editionId:string,blockId:string):T;
export function blockText(block:Block):string;
export function excerpt<T extends Document>(doc:T,editionId:string,blockId:string,from:number,to:number,options:{id:string;createdAt:string;expectedText:string}):T;
export function markdown(doc:Document,editionId:string):string;

export type EditionJob={id:string;source_snapshot_id:string;created_at:string;provider:'codex'|'claude';model?:string;binding:string;media_identity?:string;cancel_requested?:boolean;resume?:{key:string;attempt_id:string;input_digest:string}};
export type EditionAnswer={id:string;edition_id:string;block_id:string;source_snapshot_id:string;created_at:string;question:string;provider:string;model?:string;language:string;block_text:string;text:string;from:number;to:number;source_refs:string[];answer:string;citations:string[]};
export function job<T extends Document>(doc:T,options:{id:string;snapshotId:string;createdAt:string;provider:'codex'|'claude';model?:string;binding:string;mediaIdentity?:string}):T;
export function jobUpdate<T extends Document>(doc:T,id:string,patch:{resume?:EditionJob['resume'];cancel_requested?:boolean}):T;
export function receive<T extends Document>(doc:T,id:string,task:unknown,options:{createdAt:string;mediaIdentity?:string}):T;
export function answer<T extends Document>(doc:T,editionId:string,selection:{blockId:string;blockText:string;text:string;from:number;to:number},response:unknown,options:{id:string;createdAt:string;question:string;provider:string;model?:string;language:string}):T;
export function plainText(doc:Document,editionId:string):string;
export function evidenceMarkdown(doc:Document,editionId:string):string;
